function parseTwseMonth(j,date){if(j?.stat!=="OK")return[];const data=j.data||j.rows;if(!Array.isArray(data))return[];const month=date.slice(0,4)+"-"+date.slice(4,6);return data.map(r=>({date:rocToISO(r[0]),volume:num(r[1]),turnover:num(r[2]),open:num(r[3]),high:num(r[4]),low:num(r[5]),close:num(r[6]),trades:num(r[8])})).filter(x=>x.date.startsWith(month+"-")&&[x.open,x.high,x.low,x.close].every(v=>v!=null))}
