function rowObject(j,code){if(!j)return null;if(Array.isArray(j))return j.find(x=>String(pick(x,["股票代號","證券代號","SecuritiesCompanyCode","SecuritiesCode","Code"])||"").trim()===code)||null;for(const t of j.tables||[]){const fields=t.fields||[],data=t.data||[],idx=fields.findIndex(x=>/股票代號|證券代號|代號/.test(x));if(idx>=0){const r=data.find(x=>String(x[idx]).trim()===code);if(r)return Object.fromEntries(fields.map((f,k)=>[f,r[k]]))}}if(Array.isArray(j.data)&&Array.isArray(j.fields)){const idx=j.fields.findIndex(x=>/股票代號|證券代號|代號/.test(x)),r=j.data.find(x=>String(x[idx]).trim()===code);if(r)return Object.fromEntries(j.fields.map((f,k)=>[f,r[k]]))}return null}
