async function extras(stock,date){const code=stock.code,ds=ymd(date);let inst=null,margin=null,val=null,rev=null;if(stock.market==="TWSE"){const [ij,mj,vj,rj]=await Promise.all([safeJson(`https://www.twse.com.tw/rwd/zh/fund/T86?date=${ds}&selectType=ALLBUT0999&response=json`,1800000),safeJson(`https://www.twse.com.tw/rwd/zh/marginTrading/MI_MARGN?date=${ds}&selectType=ALL&response=json`,1800000),safeJson("https://openapi.twse.com.tw/v1/exchangeReport/BWIBBU_ALL",3600000),safeJson("https://openapi.twse.com.tw/v1/opendata/t187ap05_L",3600000)]);inst=institutionalFrom(rowObject(ij,code));margin=marginFrom(rowObject(mj,code));val=valuationFrom(rowObject(vj,code));rev=revenueFrom(rowObject(rj,code))}else{const [ij,mj,vj,rj]=await Promise.all([safeJson("https://www.tpex.org.tw/openapi/v1/tpex_3insti_daily_trading",1800000),safeJson("https://www.tpex.org.tw/openapi/v1/tpex_margin_balance",1800000),safeJson("https://www.tpex.org.tw/openapi/v1/tpex_mainboard_peratio_analysis",3600000),safeJson("https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap05_O",3600000)]);inst=institutionalFrom(rowObject(ij,code));margin=marginFrom(rowObject(mj,code));val=valuationFrom(rowObject(vj,code));rev=revenueFrom(rowObject(rj,code))}return{institutional:inst,margin,valuation:val,revenue:rev,status:{institutional:!!inst,margin:!!margin,valuation:!!val,revenue:!!rev}}}
