async function scanStocks(raw){const codes=[...new Set(String(raw||"").split(/[\s,，;；]+/).map(x=>x.trim()).filter(Boolean))].slice(0,12);if(!codes.length)throw new Error("請輸入至少一檔股票代碼或名稱");const jobs=codes.map(async q=>{try{const stock=await resolve(q),rows=await history(stock,5,latestCompletedDate());validateHistoryDates(rows);const analysis=analyze(rows),extra=await extras(stock,analysis.date),score=composite(analysis,extra),supportGap=analysis.support1?Math.abs(analysis.support1.distance):null,breakoutGap=analysis.breakout?analysis.breakout.distance:null,inst=extra.institutional||{},tags=[];if(supportGap!=null&&supportGap<=.015)tags.push("接近支撐");if(breakoutGap!=null&&breakoutGap>=0&&breakoutGap<=.02)tags.push("接近突破");if(analysis.volumeBreakout)tags.push("量價突破");if((inst.foreign||0)>0&&(inst.trust||0)>0)tags.push("外投同買");if((inst.total||0)>0)tags.push("法人偏多");if(analysis.trend==="偏多")tags.push("技術偏多");if(score.structure>=70)tags.push("高共振");let observation=score.structure+(tags.includes("接近支撐")?6:0)+(tags.includes("接近突破")?6:0)+(tags.includes("量價突破")?8:0)+(tags.includes("外投同買")?5:0);observation=Math.max(0,Math.min(100,Math.round(observation)));return{ok:true,stock,date:analysis.date,current:analysis.current,changePct:analysis.changePct,trend:analysis.trend,structure:score.structure,observation,support:analysis.support1?{price:analysis.support1.price,distance:analysis.support1.distance,confidence:analysis.support1.confidence}:null,breakout:analysis.breakout?{price:analysis.breakout.price,distance:analysis.breakout.distance,confidence:analysis.breakout.confidence}:null,volumeRatio:analysis.volumeRatio,tags}}catch(e){return{ok:false,query:q,error:e.message||String(e)}}});const results=await Promise.all(jobs);return results.sort((a,b)=>(b.ok?b.observation:-1)-(a.ok?a.observation:-1))}
