export default{async fetch(request,env){const u=new URL(request.url);if(u.pathname==="/api/stock"){if(request.method!=="POST")return new Response(JSON.stringify({error:"Method not allowed"}),{status:405,headers:{"content-type":"application/json"}});try{const input=await request.json();if(!["analyze","scan","search"].includes(input.action))throw new Error("無效操作");if(input.asOf&&!/^\d{4}-\d{2}-\d{2}$/.test(input.asOf))throw new Error("日期格式錯誤");const out=await engine(input,env);return new Response(JSON.stringify(out),{headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store"}})}catch(e){return new Response(JSON.stringify({error:e?.message||"分析失敗"}),{status:400,headers:{"content-type":"application/json;charset=UTF-8"}})}}const asset=await env.ASSETS.fetch(request);const headers=new Headers(asset.headers);if(["/","/index.html","/app.js","/styles.css","/sw.js"].includes(u.pathname))headers.set("cache-control","no-store, no-cache, must-revalidate, max-age=0");return new Response(asset.body,{status:asset.status,statusText:asset.statusText,headers})}};
